// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2010, "6-7", [{"author":"А. Сомин","question":"Какой из этих глаголов родствен числительному?","choices":["стричь","учетверять","пятиться","шествовать","семенить"],"key":"Б","review":["Что значит «учетверить»","Учетверить — сделать в четыре раза больше. Слышится и числительное «четыре».","«Пятиться» связано с пяткой, «шествовать» — с движением, а «семенить» — с мелкими частыми шагами."]},{"author":"Л. Фёдорова","question":"Какое из слов русское по происхождению?","choices":["карандаш","ручка","тетрадь","портфель","рюкзак"],"key":"Б","review":["Исконное и заимствованное","«Ручка» образовано от русского слова «рука» с помощью суффикса -к-.","«Карандаш», «тетрадь», «портфель» и «рюкзак» пришли из других языков."]},{"author":"И. Иткин","question":"Смысл какого из этих предложений мало изменится, если опустить частицу не?","choices":["Он ещё не здесь.","Когда-то я не любил ходить пешком.","Я давно не перечитывал эту книгу.","Скажи ему, чтобы в следующий раз не приходил.","Он единственный, кто не должен за это отвечать"],"key":"В","review":["Давность действия","«Давно не перечитывал эту книгу» значит, что с прошлого чтения прошло много времени.","«Давно перечитывал эту книгу» тоже относит последнее чтение к далёкому прошлому. В других фразах удаление «не» меняет мысль на противоположную."]},{"author":"И. Иткин","question":"Педро родился в Барселоне. Как правильно заполнить пропуск во фразе: Педро — ... Барселоны?","choices":["урождённый","уродитель","урожденец","уроженец","среди вариантов (А)–(Г) нет правильного"],"key":"Г","review":["Где он родился","Сравни обычные сочетания «уроженец Москвы», «уроженец города» и «уроженец этой страны».","По той же схеме говорят «Педро — уроженец Барселоны». Пишется без д."]},{"author":"Н. Валеева","question":"Что можно сделать и с бананом, и с водой, и с помещением?","choices":["съесть","выпить","проветрить","вымыть","очистить"],"key":"Д","review":["Глагол для трёх предметов","Банан очищают от кожуры, воду — от примесей, помещение — от мусора.","Для каждого действия подходит «очистить», хотя способ очистки различен."]},{"author":"К. Гилярова","question":"Какое из этих слов лишнее по смыслу?","choices":["глазомер","секундомер","шагомер","угломер","силомер"],"key":"А","review":["Точность измерения","Секундомер, шагомер, угломер и силомер — измерительные приборы.","Глазомер — способность человека оценивать расстояние и величину на глаз."]},{"author":"Е. Вельмезова","question":"Даны существительные — названия блюд: мороженое, жаркое, горячее, сладкое, первое. Сколько из них по произношению и написанию совпадает со словами других частей речи?","choices":["одно","два","три","четыре","пять"],"key":"Г","review":["Одинаковые слова о еде","Есть «моро́женое мясо», «горя́чее молоко», «сла́дкое яблоко» и «пе́рвое место». Формы прилагательных и числительного совпадают с названиями еды.","Название блюда «жарко́е» по ударению отличается от прилагательного «жа́ркое», поэтому считаются четыре слова."]},{"author":"М. Вогман и Л. Типисева","question":"Как правильно закончить фразу: Помог бы, что ли, а то всё стоишь …?","choices":["руки в боки","руки в ноги","ноги в руки","нога за ногу","руки-крюки"],"key":"А","review":["Как стоят без дела","О том, кто упёр руки в бока, говорят «стоит руки в боки».","«Ноги в руки» означает поспешить, а «нога за ногу» описывает медленную ходьбу."]},{"author":"Е. Добрушина","question":"В каком из этих списков одно из понятий «выпадает» по смыслу из общего ряда?","choices":["род, падеж, число","существительное, прилагательное, сказуемое","приставка, суффикс, окончание","родительный, дательный, винительный","мужской, женский, средний"],"key":"Б","review":["Часть речи и член предложения","Существительное и прилагательное — части речи. Они определяются по значению и грамматическим свойствам слова.","Сказуемое — член предложения, то есть роль слова или сочетания слов в предложении."]},{"author":"А. Пиперски","question":"У какого из этих существительных форма множественного числа образуется не совсем так, как у остальных?","choices":["гусёнок","дошколёнок","жеребёнок","тигрёнок","чертёнок"],"key":"Д","review":["Что меняется во множественном","Обычно -ёнок меняется на -ята: «гусята», «дошколята», «жеребята», «тигрята».","У «чертёнка» нормативная форма «чертенята»: по сравнению с другими примерами в суффиксе сохраняется слог -ен-."]},{"author":"И. Иткин","question":"Даны слова: расти, оживи, буди. Какие из них можно понять как формы повелительного наклонения двух разных глаголов?","choices":["никакие","только расти","расти и оживи","оживи и буди","все"],"key":"В","review":["Два повелительных значения","«Расти большой» связано с «расти», «расти цветы» — с «растить». Написание и произношение совпадают.","«Оживи поскорее» может относиться к «ожить», а «оживи рисунок» — к «оживить». «Буди» образовано от «будить»."]},{"author":"Б. Иомдин","question":"В сказке А. С. Пушкина о царе Салтане есть такие строки:\nВ чешуе, как жар горя,\nИдут витязи четами…\nСлово четами означает «парами». А что здесь означает слово жар?","choices":["горячий воздух","высокая температура","раскалённые угли","румянец","пыл, страсть"],"key":"В","review":["Что светится, как жар","Витязи идут в блестящей чешуе, поэтому сравнение говорит о её ярком свечении.","«Жар» здесь — раскалённые угли. Они тлеют и светятся красным."]},{"author":"О. Шеманаева","question":"В каком падеже стоит слово пенсне в предложении из повести М. А. Булгакова «Собачье сердце»: «Филипп Филиппович оседлал нос пенсне поверх очков и принялся читать»?","choices":["в именительном","в родительном","в дательном","в винительном","в творительном"],"key":"Д","review":["Падеж неизменяемого слова","Форма «пенсне» внешне не меняется. Подбери к нему вопрос от глагола: «Оседлал нос чем?».","Ответ «пенсне» на «чем?» служит дополнением в творительном падеже."]},{"author":"Б. Иомдин","question":"Выберите пару синонимов:","choices":["скачивать — раскачивать","скручивать — раскручивать","спиливать — распиливать","сплющивать — расплющивать","скалиться — раскалиться"],"key":"Г","review":["Одинаковый результат","«Сплющивать» и «расплющивать» оба обозначают превращение во что-то плоское нажимом или ударом.","Скручивать и раскручивать, напротив, могут обозначать противоположные действия. В остальных парах значения также различаются."]},{"author":"Н. Добрушина","question":"Вчера была свадьба Сени и Маши. Пять человек так описали это событие:\nАлла: Сеня женился на Маше.\nБоря: Сеня вышел замуж за Машу.\nВаля: Маша женилась на Сене.\nГаля: Сеня и Маша поженились.\nДима: Маша вышла замуж за Сеню.\nКто из них выразился правильно?","choices":["Алла, Галя и Дима","Боря, Валя и Дима","Боря, Валя и Галя","Алла, Валя и Галя","все пятеро"],"key":"А","review":["Как говорят о свадьбе","Мужчина женится на женщине, женщина выходит замуж за мужчину, а о двоих можно сказать «поженились».","Эти модели соблюдают Алла, Галя и Дима."]},{"author":"С. Бурлак","question":"От какого глагола нельзя образовать парный ему глагол несовершенного вида?","choices":["встретиться","смутиться","очутиться","оказаться","отказаться"],"key":"В","review":["Глагол без пары","Сравни «встретиться — встречаться», «смутиться — смущаться», «оказаться — оказываться», «отказаться — отказываться».","К «очутиться» общеупотребительной формы несовершенного вида нет. В зависимости от смысла её заменяют другим глаголом, например «оказываться»."]},{"author":"О. Шеманаева","question":"В каком предложении есть грамматическая ошибка?","choices":["Он в бассейне не только плавает, но и прыгает с вышки.","Он не только в бассейне плавает, но и в пруду.","Он плавает не только в бассейне, но и в пруду.","Он не только плавает в бассейне, но и играет в городки.","Он плавает не только в бассейне, но и играет в городки"],"key":"Д","review":["Границы парного союза","Союз «не только … но и …» связывает грамматически равноправные части: два места или два действия.","В варианте Д после «не только» стоит место «в бассейне», а после «но и» — действие «играет». Границы частей нужно выровнять."]},{"author":"Н. Шапиро","question":"С какого сочетания букв не может начинаться слово в русском языке?","choices":["разе...","раззе...","разъе…","рассе…","расъе…"],"key":"Д","review":["Где пишут «раз» и «рас»","Есть «разевать», «раззевать», «разъезд» и «рассеять». Перед глухой с выбирают рас-.","С разделительным ъ перед е этот вариант приставки не употребляют: пишут «разъе-»."]},{"author":"Б. Иомдин","question":"Какой из этих глаголов в переводе на искусственный язык эсперанто не содержит приставки mis-?","choices":["оговориться","ослышаться","обознаться","одуматься","обсчитаться"],"key":"Г","review":["Что обозначает «ошибиться»","Оговориться, ослышаться, обознаться и обсчитаться — ошибиться в речи, восприятии слов, узнавании или счёте.","«Одуматься» значит пересмотреть своё решение. Значение ошибки, которое передаёт mis-, этому действию не нужно."]},{"author":"Б. Иомдин","question":"Из множества часто встречающихся написаний этого наречия правильно только одно. Какое?","choices":["из подтишка","из-под тишка","из-под тяжка","исподтяжка","исподтишка"],"key":"Д","review":["Слитное наречие","«Исподтишка» относится к словам со значением «скрытно, незаметно». В настоящем языке самостоятельного слова «тишок» в таком сочетании нет.","По словарю наречие пишется слитно и начинается с ис-: «исподтишка»."]},{"author":"К. Гилярова","question":"Даны слова французского языка, оканчивающиеся на -eur, с указанием рода:\nМужской род: ascenseur — лифт, aspirateur — пылесос, ordinateur — компьютер, moteur — мотор.\nЖенский род: couleur — цвет, douceur — мягкость, profondeur — глубина, stupeur — изумление.\nКакое из следующих слов мужского рода? (Знания французского языка для решения задачи не требуется.)","choices":["froideur — холод","blancheur — белизна","saveur — вкус","vapeur — испарение","bouteur — бульдозер"],"key":"Д","review":["Приборы на -eur","Слова мужского рода в условии называют устройства, а слова женского — качества или состояния. Среди пяти вариантов только бульдозер является устройством.","Во французском род проверяют по артиклю: un bouteur — мужской род. Остальные варианты употребляются с женским артиклем: la froideur, la blancheur, la saveur, la vapeur."],"reviewedEdition":true,"keyNote":"В исходном задании bonheur «счастье» ошибочно отнесено к женскому роду. Это слово мужского рода (le bonheur). В условии оно заменено на douceur «мягкость» (la douceur). Буква Д сохранена."},{"author":"А. Лифшиц","question":"Денежной единицей Древней Руси была гривна. По-древнерусски, считая деньги, можно было сказать, например, так: пол пяты гривны. Какое количество денег обозначалось таким способом?","choices":["одна десятая гривны","четыре с половиной гривны","две с половиной гривны","пять с половиной гривен","две пятых гривны"],"key":"Б","review":["Половина пятого","Старинное «пол пяты» означает, что четыре гривны целые, а пятая имеется наполовину.","Итого четыре с половиной гривны. Та же логика видна в выражении «полвторого» о времени."]},{"author":"Н. Валеева","question":"Первоначально обои крепили к стенам:","choices":["клеем, как и теперь","гвоздями","шурупами","воском","смолой"],"key":"Б","review":["Обивка стен","«Обои» связаны со словом «обивать». Когда стены обтягивали полотном или кожей, покрытие крепили как обивку.","Его прибивали гвоздями. Бумажные обои с клеем появились позднее."]},{"author":"С. Переверзева","question":"В какой из этих фраз глагол является непереходным?","choices":["Кто же отведёт малыша домой?","А ему просто душу отвести не с кем.","Рановато сегодня развели мосты.","Что ты так мрачно руками разводишь?","Ни одна улика не навела их на след"],"key":"Г","review":["Глагол без прямого объекта","«Отвести малыша», «отвести душу», «развести мосты» и «навести их» содержат прямое дополнение.","В «разводишь руками» слово «руками» стоит в творительном. В этом обороте глагол непереходный."]},{"author":"Л. Фёдорова","question":"То, что делается просто, иногда сравнивают с одним старинным русским блюдом. А как следовало готовить это блюдо?","choices":["печь","тушить","жарить","парить","коптить"],"key":"Г","review":["Старинное простое блюдо","Фраза «проще пареной репы» сравнивает простое дело с приготовлением репы.","Слово «пареная» сохраняет название способа приготовления: репу парили."]},{"author":"А. Пиперски","question":"В каких склонениях есть хотя бы одно существительное, у которого именительный падеж единственного числа односложен?","choices":["в I скл. ж. р., во II скл. м. р., во II скл. ср. р., в III скл. и среди разносклоняемых существительных","только в I скл. ж. р., во II скл. м. р., в III скл. и среди разносклоняемых существительных","только во II скл. м. р., во II скл. ср. р., в III скл. и среди разносклоняемых существительных","только во II скл. м. р., в III скл. и среди разносклоняемых существительных","только во II скл. м. р. и в III скл"],"key":"А","review":["Односложные формы","«Тля» относится к первому склонению женского рода, «дом» — ко второму мужского, «дно» — ко второму среднего.","«Ночь» даёт пример третьего склонения, «путь» — разносклоняемого существительного. Во всех случаях в начальной форме одна гласная."]},{"author":"К. Гилярова","question":"Маленький Никита произносит одинаково [ф] и [ш]. Какие слова мама не может различить в его речи: (1) кафтан и каштан, (2) фары и шары, (3) рожь и ров, (4) фарш и шарф?","choices":["только (1) и (2)","только (1), (2) и (4)","только (1), (3) и (4)","только (4)","(1), (2), (3) и (4)"],"key":"В","review":["Звуки и место ударения","В «кафтане» и «каштане» различаются [ф] и [ш]. В «рожь» и «ров» именно эти звуки получаются после оглушения конечных ж и в. Похожим образом сливаются «фарш» и «шарф».","«Фа́ры» и «шары́» даже при одинаковом согласном отличаются ударением."]},{"author":"А. Пиперски","question":"Вот стихотворение Д. Д. Минаева:\nДав(0) кричал я: «Уто(+),\nКогда на Лизе не женюсь!»?\nИ вот теперь твой муж, смо(3),\nК ка(…)евши, размышляет:\n«Кто женится, чёрт побери,\nТот в сумас(6)вии блуждает».\nЧто должно стоять на месте многоточия?","choices":[".",",","−","8","9"],"key":"В","review":["Читаем название знака","Цифры и знаки читаются по названию. Так, «уто(+)» звучит «утоплюсь», а «смо(3)» — «смотри».","«К ка(−)евши» читается «к камину севши»: в середину строки вставили название «минус»."]},{"author":"Л. Иомдин","question":"Что по смыслу лишнее?","choices":["сообщение о пожаре в Японии","сообщение о погоде в Москве","сообщение о запуске космического корабля","сообщение о рождении королевского наследника","сообщение о прибытии поезда"],"key":"Б","review":["Что именно сообщают","Пожар, запуск корабля, рождение наследника и прибытие поезда — отдельные события.","Сообщение о погоде описывает состояние или даёт прогноз, а остальные сообщают о событии."]},{"author":"А. Сомин","question":"В польском языке есть два слова, соответствующих русскому что — co (цо) и że (же). Даны предложения, в которых слово что переведено на польский язык:\n1. Анджей уже понял, что (co) у тебя лежит в рюкзаке.\n2. Я думаю, что (że) он уже дома.\n3. Мама ещё не знает, что (co) здесь произошло.\nДаны ещё два предложения.\n4. Кшиштоф догадывается, что Михал ему напишет.\n5. Мне кажется, что здесь что-то не так.\nКак слово что в этих предложениях будет переведено на польский язык?","choices":["4 — co, 5 — можно и co, и że","4 — co, 5 — że","4 — можно и co, и że, 5 — że","4 — że, 5 — co","4 — можно и co, и że, 5 — можно и co, и że"],"key":"В","review":["Два значения «что»","В польском co означает «какую вещь» или «какое событие», а że вводит содержание мысли или сообщения.","Михал либо напишет что-то определённое — co, либо вообще напишет — że. После «мне кажется» в пятом предложении нужно że."]}], {"year":2010,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"6-7-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2010.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
